#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Puts Ore Cloud online for the first time (#550): a Hetzner server, a domain pointing at it, the server's
# secret, the first deploy. Run it on the Mac from the repo: packages/cloud/deploy/setup.sh
# Safe to run again: it remembers the answers, and never replaces the server's secret (that would sign everyone out).
# Where a site's screens are named, they are as of 2026-11; if one has moved, the field names still hold.

run_wizard() {

TOTAL_STAGES=6
ENV_FILE="$HOME/.ore-cloud-setup"
KEY="$HOME/.ssh/ore-cloud"
REPO=$(cd "$(dirname "$0")/../../.." && pwd)
# The address is given each time, so an older `ore-cloud` entry with another address can't mislead it.
on_server() { ssh -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 -o HostName="$ORE_HOST" ore-cloud "$@"; }

banner "Put Ore Cloud online"

stage "A Hetzner account"
say "Hetzner rents the one server Ore Cloud runs on."
open_url "https://console.hetzner.cloud/"
step "Sign up (or sign in). It asks for a payment method, and may ask to verify who you are."
step "Create a project and name it Ore."
pause "Press Enter when you are looking at the empty project"

stage "A key for the server"
say "The server lets in whoever holds this key, and nobody by password."
mkdir -p "$HOME/.ssh" && chmod 700 "$HOME/.ssh"
if [[ ! -f "$KEY" ]]; then
  ssh-keygen -q -t ed25519 -N "" -C "ore-cloud" -f "$KEY"
  printf '  %s✓ made%s %s\n' "$GREEN" "$RESET" "$KEY"
fi
if command -v pbcopy >/dev/null 2>&1; then pbcopy < "$KEY.pub"; say "Its public half is on your clipboard."
else say "Its public half:"; say "$(cat "$KEY.pub")"; fi
step "In the Ore project: Security, then SSH keys, then Add SSH key. Paste, name it ore-cloud, save."
pause "Press Enter when the key is listed"

stage "The server"
say "In the Ore project, add a server with these choices:"
step "Location: any. In Germany or Finland it costs about half of the US ones, and the distance doesn't matter here."
step "Image: Ubuntu 24.04"
step "Type: shared vCPU, x86, with 4 vCPUs and 8 GB of RAM (about \$8 a month in Europe)"
step "Networking: keep public IPv4 on"
step "SSH keys: tick ore-cloud"
step "Name: ore-cloud. Leave the rest off. Create it."
ask ORE_HOST "Paste the server's IPv4 address:"
[[ "$ORE_HOST" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || { warn "That doesn't look like an IPv4 address. Run the wizard again."; exit 1; }
write_env ORE_HOST "$ORE_HOST"
# One name for the server, so deploy.sh and you can both say `ore-cloud`.
touch "$HOME/.ssh/config"
if grep -q '^Host ore-cloud$' "$HOME/.ssh/config"; then
  grep -A4 '^Host ore-cloud$' "$HOME/.ssh/config" | grep -q "HostName $ORE_HOST\$" ||
    { warn "~/.ssh/config has ore-cloud at another address. Change its HostName to $ORE_HOST, then run this again."; exit 1; }
else
  printf '\nHost ore-cloud\n  HostName %s\n  User root\n  IdentityFile %s\n  IdentitiesOnly yes\n' "$ORE_HOST" "$KEY" >> "$HOME/.ssh/config"
fi
say "Checking the server answers..."
tries=0
until err=$(on_server true 2>&1); do
  tries=$((tries + 1))
  note "not yet, trying again in 10 s (Ctrl-C to stop)"
  (( tries % 3 )) || note "ssh says: ${err##*$'\n'}"
  sleep 10
done
printf '  %s✓ the server answers%s\n' "$GREEN" "$RESET"

stage "A domain"
say "Ore Cloud needs a name, for HTTPS and for the apps to find it."
say "Any registrar works. If you have none, Porkbun and Cloudflare are both plain and cheap (about \$12 a year for a .com)."
open_url "https://porkbun.com/"
step "Buy a domain, or use one you own."
step "In its DNS settings add one record: type A, host cloud, answer $ORE_HOST. Delete any other record for cloud."
ask ORE_DOMAIN "The full name, like cloud.yourdomain.com:"
ORE_DOMAIN=${ORE_DOMAIN#https://}; ORE_DOMAIN=${ORE_DOMAIN%/}
[[ "$ORE_DOMAIN" =~ ^[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]] || { warn "That doesn't look like a domain name. Run the wizard again."; exit 1; }
write_env ORE_DOMAIN "$ORE_DOMAIN"
say "Waiting for $ORE_DOMAIN to point at $ORE_HOST. A new record can take a few minutes."
until [[ "$(dig +short A "$ORE_DOMAIN" @1.1.1.1 | tail -n1)" == "$ORE_HOST" ]]; do note "not yet, trying again in 20 s (Ctrl-C to stop; run again later and it picks up here)"; sleep 20; done
printf '  %s✓ %s points at the server%s\n' "$GREEN" "$ORE_DOMAIN" "$RESET"

stage "The server's own setup"
say "Nothing for you to click: this installs Docker and gives the server its secret."
note "The secret signs every session. It is made on the server and never leaves it."
on_server "ORE_DOMAIN='$ORE_DOMAIN' sh -s" <<'REMOTE'
set -eu
command -v docker >/dev/null 2>&1 || { curl -fsSL https://get.docker.com | sh >/dev/null; }
umask 077
touch /etc/ore-cloud.env
if ! grep -q '^ORE_SESSION_SECRET=.' /etc/ore-cloud.env; then
  secret=$(openssl rand -base64 48 | tr -d '\n')
  [ "${#secret}" -ge 32 ]
  echo "ORE_SESSION_SECRET=$secret" >> /etc/ore-cloud.env
fi
grep -v '^ORE_DOMAIN=' /etc/ore-cloud.env > /etc/ore-cloud.env.new || true
echo "ORE_DOMAIN=$ORE_DOMAIN" >> /etc/ore-cloud.env.new
mv /etc/ore-cloud.env.new /etc/ore-cloud.env
docker --version
REMOTE
printf '  %s✓ the server is ready%s\n' "$GREEN" "$RESET"
pause

stage "The first deploy"
say "This sends Ore Cloud to the server, starts it, and checks https://$ORE_DOMAIN/health. A few minutes the first time."
if confirm "Deploy now?"; then
  "$REPO/packages/cloud/deploy/deploy.sh" ore-cloud
  pause "Press Enter to finish"
else
  SKIPPED+=("the deploy: packages/cloud/deploy/deploy.sh ore-cloud")
fi

finish
say "To put a newer Ore Cloud on the server later: packages/cloud/deploy/deploy.sh ore-cloud"
printf '\n'
}

run_wizard "$@"; exit
